"""Weekly fictional photo issues, with stable editorial and per-cut image bindings.

Editorial workflow: docs/EDITORIAL_LOOP.md (成人の軽い未来企画).
Character/reference data is internal and is never passed into reader markup.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
INDEX_URL = "/photo/weekly/"
FEED_URL = "/feeds/weekly-photo.xml"
MIN_SWIMWEAR_CUTS = 6
# Only editorial meaning enters this fingerprint. Release state/timestamps and
# image transport, adoption/review, file paths and generated bytes stay outside.
EDITORIAL_FIELDS = ("slug", "number", "title", "summary", "setting", "column",
                    "model_id", "model_snapshot", "source_article", "shots")
ARTICLE_FIELDS = ("slug", "title", "summary", "category", "paragraphs", "scene_prompt")


def issue_fingerprint(issue):
    editorial = {key: issue[key] for key in EDITORIAL_FIELDS}
    encoded = json.dumps(editorial, ensure_ascii=False, sort_keys=True,
                         separators=(",", ":"), allow_nan=False).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def index_url():
    return INDEX_URL


def feed_url():
    return FEED_URL


def issue_url(issue):
    return INDEX_URL + issue["slug"] + "/"


def image_path(issue, cut_id):
    return "assets/generated/photo-issue-" + issue["slug"] + "-" + cut_id + ".jpg"


def photo_image_url(issue, cut_id):
    image = issue["images"][cut_id]
    return issue_url(issue) + cut_id + ".jpg?v=" + image["sha256"][:12]


def cover_shot(issue):
    cut = issue.get("cover_cut_id", issue["shots"][0]["id"])
    return next(shot for shot in issue["shots"] if shot["id"] == cut)


def cover_url(issue):
    return photo_image_url(issue, cover_shot(issue)["id"])


# Reuse the news image archive's limits and counter; gallery JPEGs live in its
# direct directory, while source PNGs/candidate receipts never enter dist.
import re
from datetime import datetime, timezone
if __package__:
    from .photo_body_profiles import validate_body_profile, validate_body_reference
    from .photo_issue_plan import freeze_model_plan, generation_inputs
    from .generated_photos import (MAX_SCENE_BYTES, MAX_ARCHIVE_BYTES, article_fingerprint,
                                   generation_record_fingerprint, accepted_review_matches)
    from .local_scene_photos import archive_bytes
    from .media_policy import jpeg_dimensions
else:
    from photo_body_profiles import validate_body_profile, validate_body_reference
    from photo_issue_plan import freeze_model_plan, generation_inputs
    from generated_photos import (MAX_SCENE_BYTES, MAX_ARCHIVE_BYTES, article_fingerprint,
                                 generation_record_fingerprint, accepted_review_matches)
    from local_scene_photos import archive_bytes
    from media_policy import jpeg_dimensions

SLUG = re.compile(r"[a-z0-9]+(?:-[a-z0-9]+)*\Z")
SHA = re.compile(r"[0-9a-f]{64}\Z")
GIT = re.compile(r"[0-9a-f]{40}\Z")
# These named mood/light references are internal; none is a depicted person.
INTERNAL_REFERENCE_NAMES = ("藤嶌果歩", "齋藤飛鳥")


def _text(value, label):
    if not isinstance(value, str) or not value.strip():
        raise ValueError("Missing photo issue " + label)
    return value


def _stamp(value):
    try:
        stamp = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except (AttributeError, TypeError, ValueError) as exc:
        raise ValueError("Invalid photo issue publication/review timestamp") from exc
    if stamp.tzinfo is None:
        raise ValueError("Photo issue timestamp needs a timezone")
    return stamp


def _local(root, relative):
    if not isinstance(relative, str) or Path(relative).is_absolute() or ".." in Path(relative).parts:
        raise ValueError("Unsafe photo issue path")
    current = Path(root)
    for part in Path(relative).parts:
        current = current / part
        if current.is_symlink():
            raise ValueError("Photo issue symlinks are not permitted")
    return current


def _master(master):
    if (not isinstance(master, dict) or not SHA.fullmatch(str(master.get("sha256", "")))
            or not SHA.fullmatch(str(master.get("source_png_sha256", "")))
            or not re.fullmatch(r"assets/(?:generated|casters)/[a-z0-9-]+\.jpg", str(master.get("path", "")))
            or not isinstance(master.get("provenance"), str) or not master["provenance"].startswith("assets/")):
        raise ValueError("Invalid photo model master reference")



def _editorial_history(issue):
    """Return verified snapshots; history does not change the current fingerprint."""
    entries = issue.get("editorial_history", [])
    if not isinstance(entries, list):
        raise ValueError("Photo editorial_history must be a snapshot list")
    history = {}
    for entry in entries:
        if not isinstance(entry, dict) or not isinstance(entry.get("editorial"), dict):
            raise ValueError("Invalid photo editorial history snapshot")
        editorial, sha = entry["editorial"], entry.get("issue_sha256")
        if (set(editorial) != set(EDITORIAL_FIELDS) or not SHA.fullmatch(str(sha))
                or issue_fingerprint(editorial) != sha or sha == issue["issue_sha256"] or sha in history
                or any(editorial.get(key) != issue[key] for key in ("slug", "number", "model_id"))):
            raise ValueError("Photo editorial history fingerprint/identity mismatch")
        _text(entry.get("reason"), "editorial history reason")
        shots = editorial["shots"]
        if (not isinstance(shots, list) or len(shots) != 10
                or any(not isinstance(shot, dict) or shot.get("id") != f"{number:02}"
                       for number, shot in enumerate(shots, 1))):
            raise ValueError("Invalid historical photo cuts")
        for key in ("images", "generation_holds"):
            if (not isinstance(entry.get(key), dict)
                    or set(entry[key]) - {shot["id"] for shot in shots}):
                raise ValueError("Photo history needs original images and generation holds")
        studies = entry.get("studies", {})
        if not isinstance(studies, dict):
            raise ValueError("Photo history studies must be original native records")
        for logical, study in studies.items():
            if (not isinstance(logical, str) or sha not in logical or not isinstance(study, dict)
                    or set(study) != {"sha256", "bytes", "source_png_sha256", "provenance"}
                    or not isinstance(study.get("provenance"), dict)
                    or study["provenance"].get("logical_run_id") != logical):
                raise ValueError("Invalid registered photo study")
        source = editorial["source_article"]
        if (not isinstance(source, dict) or not SLUG.fullmatch(str(source.get("slug", "")))
                or not SHA.fullmatch(str(source.get("article_sha256", "")))):
            raise ValueError("Invalid historical photo source binding")
        snapshot = editorial["model_snapshot"]
        if not isinstance(snapshot, dict) or snapshot.get("id") != issue["model_id"]:
            raise ValueError("Invalid historical photo model")
        _master(snapshot.get("master"))
        history[sha] = entry
    return history



def _article_photo_sources(issue):
    """Frozen evidence of the accepted source/master, independent of later text edits."""
    sources = issue.get("article_photo_sources", {})
    if not isinstance(sources, dict) or set(sources) - {issue["source_article"]["slug"]}:
        raise ValueError("Photo issue article sources must match its source article")
    for slug, snapshot in sources.items():
        if (not isinstance(snapshot, dict)
                or set(snapshot) != {"article", "manifest", "accepted_review", "snapshot_sha256"}):
            raise ValueError("Invalid accepted article-photo snapshot")
        article, manifest, review = (snapshot["article"], snapshot["manifest"], snapshot["accepted_review"])
        content = {key: snapshot[key] for key in ("article", "manifest", "accepted_review")}
        master, source = issue["model_snapshot"]["master"], issue["source_article"]
        if (not isinstance(article, dict) or set(article) != set(ARTICLE_FIELDS)
                or article.get("slug") != slug or article_fingerprint(article) != source["article_sha256"]
                or snapshot["snapshot_sha256"] != generation_record_fingerprint(content)
                or not isinstance(manifest, dict) or manifest.get("article_sha256") != source["article_sha256"]
                or manifest.get("origin") != "chatgpt-imagegen" or manifest.get("model") != "ChatGPT ImageGen"
                or manifest.get("sha256") != master["sha256"]
                or manifest.get("source_png_sha256") != master["source_png_sha256"]
                or master["path"] != "assets/generated/" + slug + ".jpg"
                or not accepted_review_matches(review, source["article_sha256"], manifest["sha256"])
                or review.get("generation_record_sha256") != generation_record_fingerprint(manifest)):
            raise ValueError("Accepted article-photo snapshot fingerprint/review mismatch")
        native = manifest.get("native_candidate")
        if (not isinstance(native, dict)
                or native.get("receipt_path") != "maintenance/native-image-candidates/" + slug + "/receipt.json"):
            raise ValueError("Accepted article photo lacks original native provenance")
    return sources


def _article_generation_source(issue, image, cut):
    adoption = image["adoption"]
    if (set(adoption) != {"kind", "source_article_slug", "source_article_sha256",
                         "target_issue_sha256", "target_cut_id", "reason"}
            or adoption.get("target_issue_sha256") != issue["issue_sha256"]
            or adoption.get("target_cut_id") != cut or adoption.get("source_article_slug") != issue["source_article"]["slug"]
            or adoption.get("source_article_sha256") != issue["source_article"]["article_sha256"]):
        raise ValueError("Invalid accepted article-photo adoption target/source")
    _text(adoption.get("reason"), "article-photo adoption reason")
    snapshot = _article_photo_sources(issue).get(adoption["source_article_slug"])
    if snapshot is None:
        raise ValueError("Accepted article-photo adoption needs its frozen source snapshot")
    manifest, original = snapshot["manifest"], snapshot["accepted_review"]
    native, provenance = manifest["native_candidate"], image["provenance"]
    if (any(image.get(key) != manifest.get(key) for key in ("sha256", "bytes", "source_png_sha256"))
            or any(provenance.get(key) != native.get(old_key) for key, old_key in
                   (("candidate_branch", "branch"), ("candidate_commit", "commit"),
                    ("logical_run_id", "logical_run_id"), ("receipt_sha256", "receipt_sha256")))
            or _stamp(original["reviewed_at"]) >= _stamp(image["review"].get("reviewed_at"))):
        raise ValueError("Accepted article-photo origin changed or target review is stale")
    return issue["source_article"]


def _generation_source(issue, image, cut):
    """Only explicit adoption can use an immutable older generation identity."""
    logical = image["provenance"].get("logical_run_id", "")
    adoption = image.get("adoption")
    if isinstance(adoption, dict) and adoption.get("kind") == "accepted_article_photo":
        return _article_generation_source(issue, image, cut)
    if adoption is None:
        if (not isinstance(logical, str) or issue["issue_sha256"] not in logical
                or not re.search(r"(?:^|[-/:])cut[-_:]?" + cut + r"(?:$|[-/:])", logical)):
            raise ValueError("Invalid photo issue generation reference")
        return issue["source_article"]
    if (not isinstance(adoption, dict)
            or set(adoption) != {"source_issue_sha256", "target_issue_sha256", "target_cut_id", "reason"}
            or adoption.get("target_issue_sha256") != issue["issue_sha256"]
            or adoption.get("target_cut_id") != cut):
        raise ValueError("Invalid explicit photo adoption target")
    _text(adoption.get("reason"), "adoption reason")
    source_fp = adoption.get("source_issue_sha256")
    if not SHA.fullmatch(str(source_fp)):
        raise ValueError("Invalid photo adoption source fingerprint")
    entry = _editorial_history(issue).get(source_fp)
    if (entry is None or not isinstance(logical, str) or source_fp not in logical):
        raise ValueError("Photo adoption lacks its original editorial history/generation")
    if entry["editorial"]["model_snapshot"] != issue["model_snapshot"]:
        raise ValueError("Photo adoption changed the fixed model/master snapshot")
    reviews = image.get("review_history")
    if not isinstance(reviews, list) or any(not isinstance(review, dict) for review in reviews):
        raise ValueError("Photo adoption needs original review_history")
    # Previously accepted bytes keep their entire raw provenance and old review.
    # Only a registered successful native study can lack a prior acceptance.
    original_acceptance = False
    for old_cut, original in entry["images"].items():
        if not isinstance(original, dict) or original.get("sha256") != image["sha256"]:
            continue
        original_acceptance = True
        old_review = original.get("review")
        if (original.get("provenance") != image["provenance"]
                or original.get("source_png_sha256") != image.get("source_png_sha256")
                or original.get("bytes") != image.get("bytes") or not isinstance(old_review, dict)
                or old_review not in reviews or old_review.get("decision") != "accepted"
                or old_review.get("issue_sha256") != source_fp
                or old_review.get("image_sha256") != image["sha256"] or old_review.get("cut_id") != old_cut
                or old_review.get("master_sha256") != entry["editorial"]["model_snapshot"]["master"]["sha256"]
                or _stamp(old_review.get("reviewed_at")) >= _stamp(image["review"].get("reviewed_at"))):
            raise ValueError("Photo adoption changed original provenance/review history")
    if not original_acceptance:
        study = entry.get("studies", {}).get(logical)
        if (not isinstance(study, dict) or reviews != []
                or any(study.get(key) != image.get(key) for key in
                       ("sha256", "bytes", "source_png_sha256", "provenance"))):
            raise ValueError("Photo adoption is not a registered unaccepted native study")
    return entry["editorial"]["source_article"]


def validate_catalog(data):
    if not isinstance(data, dict) or data.get("schema_version") != 1:
        raise ValueError("Invalid photo issue catalog")
    models, issues = data.get("models"), data.get("issues")
    if not isinstance(models, list) or not 1 <= len(models) <= 7 or not isinstance(issues, list):
        raise ValueError("Invalid photo models/issues")
    model_ids = set()
    for model in models:
        if (not isinstance(model, dict) or not SLUG.fullmatch(str(model.get("id", "")))
                or model["id"] in model_ids or model.get("fictional") is not True
                or type(model.get("age")) is not int or not 20 <= model["age"] <= 99):
            raise ValueError("Invalid fictional adult photo model")
        _text(model.get("name"), "model name")
        if any(name in model["name"] for name in INTERNAL_REFERENCE_NAMES):
            raise ValueError("Internal reference name used as a public photo model")
        character = model.get("character")
        if not isinstance(character, dict):
            raise ValueError("Photo model needs a character definition")
        for key in ("first_person", "voice", "weakness"):
            _text(character.get(key), "character " + key)
        personality = character.get("personality")
        if isinstance(personality, str):
            _text(personality, "character personality")
        elif isinstance(personality, list) and personality:
            for trait in personality:
                _text(trait, "character personality")
        else:
            raise ValueError("Photo model needs a character personality")
        likes = character.get("likes")
        if not isinstance(likes, list) or not likes:
            raise ValueError("Photo model needs character likes")
        for item in likes:
            _text(item, "character like")
        if model.get("reference_state") not in ("accepted_reference", "preview_only", "unprepared"):
            raise ValueError("Invalid photo model reference state")
        if model.get("master") is not None:
            _master(model["master"])
        elif model.get("reference_state") != "unprepared":
            raise ValueError("Prepared photo model lacks a master")
        validate_body_profile(model.get("body_profile"))
        validate_body_reference(model.get("body_reference"))
        model_ids.add(model["id"])
    seen, numbers = set(), set()
    for issue in issues:
        if (not isinstance(issue, dict) or not SLUG.fullmatch(str(issue.get("slug", "")))
                or issue["slug"] in seen or type(issue.get("number")) is not int
                or issue["number"] < 1 or issue["number"] in numbers
                or issue.get("state") not in ("draft", "published") or issue.get("model_id") not in model_ids):
            raise ValueError("Invalid photo issue identity/state")
        for key in ("title", "summary"):
            _text(issue.get(key), key)
        snapshot = issue.get("model_snapshot")
        if (not isinstance(snapshot, dict) or snapshot.get("id") != issue["model_id"]
                or snapshot.get("fictional") is not True or type(snapshot.get("age")) is not int
                or not 20 <= snapshot["age"] <= 99):
            raise ValueError("Invalid fixed photo model snapshot")
        _text(snapshot.get("name"), "model snapshot name")
        _text(snapshot.get("appearance"), "model appearance")
        _master(snapshot.get("master"))
        setting = issue.get("setting")
        if (not isinstance(setting, dict) or type(setting.get("year")) is not int
                or setting["year"] < 2031 or type(setting.get("month")) is not int
                or not 1 <= setting["month"] <= 12 or setting.get("aspect_ratio") != "16:9"):
            raise ValueError("Invalid fictional photo issue setting")
        _text(setting.get("location"), "location")
        _text(setting.get("visual_direction"), "visual direction")
        source = issue.get("source_article")
        if (not isinstance(source, dict) or not SLUG.fullmatch(str(source.get("slug", "")))
                or not SHA.fullmatch(str(source.get("article_sha256", "")))):
            raise ValueError("Invalid photo issue source article binding")
        if not isinstance(issue.get("column"), list) or not 1 <= len(issue["column"]) <= 6:
            raise ValueError("Invalid short photo column")
        for paragraph in issue["column"]:
            _text(paragraph, "column paragraph")
        shots = issue.get("shots")
        if not isinstance(shots, list) or len(shots) != 10:
            raise ValueError("A photo issue needs ten planned cuts")
        for number, shot in enumerate(shots, 1):
            if not isinstance(shot, dict) or shot.get("id") != f"{number:02}":
                raise ValueError("Photo cuts must be ordered 01 through 10")
            for key in ("description", "caption", "alt"):
                _text(shot.get(key), "cut " + key)
        if any(key in snapshot for key in
               ("body_profile", "body_profile_sha256", "face_reference", "body_reference")):
            generation_inputs(issue, "01")
        public_text = [issue["title"], issue["summary"], snapshot["name"], setting["location"], *issue["column"],
                       *(shot[key] for shot in shots for key in ("caption", "alt"))]
        if any(name in text for text in public_text for name in INTERNAL_REFERENCE_NAMES):
            raise ValueError("Internal photo reference name leaked into reader content")
        if (not isinstance(issue.get("images"), dict) or set(issue["images"]) - {s["id"] for s in shots}
                or issue.get("issue_sha256") != issue_fingerprint(issue)):
            raise ValueError("Photo issue meaning/fingerprint mismatch")
        holds = issue.get("generation_holds", {})
        if not isinstance(holds, dict) or set(holds) - {shot["id"] for shot in shots}:
            raise ValueError("Photo issue generation_holds must be a planned cut-ID mapping")
        _editorial_history(issue)
        _article_photo_sources(issue)
        seen.add(issue["slug"])
        numbers.add(issue["number"])
    return data


def load_photo_issues(root=ROOT):
    path = Path(root) / "content/photo_issues.json"
    if not path.exists():
        return {"schema_version": 1, "models": [], "issues": []}
    if path.is_symlink():
        raise ValueError("Unsafe photo catalog symlink")
    return validate_catalog(json.loads(path.read_text(encoding="utf-8")))


def receipt_path(issue, cut_id):
    return "maintenance/photo-issues/" + issue["slug"] + "/" + cut_id + "/receipt.json"


def validate_published_issue(issue, *, root=ROOT, now=None):
    """Verify recorded acceptance and bytes, never manufacture visual approval."""
    now = now or datetime.now(timezone.utc)
    if issue["state"] != "published" or _stamp(issue.get("published_at")) > now:
        raise ValueError("Photo issue is not released")
    if issue.get("generation_holds"):
        raise ValueError("Photo issue has unresolved generation holds")
    if issue.get("cover_cut_id", issue["shots"][0]["id"]) not in {shot["id"] for shot in issue["shots"]}:
        raise ValueError("Photo issue cover must select a reviewed cut")
    if archive_bytes(Path(root)) > MAX_ARCHIVE_BYTES:
        raise ValueError("Photo/news JPEG archive exceeds 1.5 GiB")
    master = issue["model_snapshot"]["master"]
    master_source = master["path"]
    archive = issue.get("master_archive")
    if archive is not None:
        expected = "assets/generated/photo-master-" + issue["model_id"] + "-" + master["sha256"][:12] + ".jpg"
        if (not isinstance(archive, dict) or set(archive) != {"path", "sha256"}
                or archive.get("path") != expected or archive.get("sha256") != master["sha256"]):
            raise ValueError("Photo model master archive binding mismatch")
        master_source = archive["path"]
    if hashlib.sha256(_local(root, master_source).read_bytes()).hexdigest() != master["sha256"]:
        raise ValueError("Photo model master bytes changed")
    if "body_profile" in issue["model_snapshot"]:
        _verify_plan_references(generation_inputs(issue, "01")["references"], root)
    seen_hashes = set()
    published_at = _stamp(issue["published_at"])
    framings, swimwear_count = set(), 0
    for shot in issue["shots"]:
        cut = shot["id"]
        image = issue["images"].get(cut)
        adoption = image.get("adoption") if isinstance(image, dict) else None
        is_article = isinstance(adoption, dict) and adoption.get("kind") == "accepted_article_photo"
        expected_path = master_source if is_article else image_path(issue, cut)
        if not isinstance(image, dict) or image.get("path") != expected_path:
            raise ValueError("Missing photo issue cut " + cut)
        path = _local(root, image["path"])
        size = path.stat().st_size
        if not 16_000 <= size <= MAX_SCENE_BYTES:
            raise ValueError("Photo issue cut exceeds the JPEG size limit")
        data = path.read_bytes()
        sha = hashlib.sha256(data).hexdigest()
        if (image.get("sha256") != sha or image.get("bytes") != len(data)
                or sha in seen_hashes or jpeg_dimensions(data) != (1200, 675)):
            raise ValueError("Photo issue JPEG hash/dimensions/uniqueness mismatch")
        seen_hashes.add(sha)
        provenance, review = image.get("provenance"), image.get("review")
        if not isinstance(provenance, dict) or not isinstance(review, dict):
            raise ValueError("Photo issue cut needs provenance and visual review")
        source = _generation_source(issue, image, cut)
        logical = provenance.get("logical_run_id", "")
        if (provenance.get("receipt_path") != receipt_path(issue, cut)
                or not SHA.fullmatch(str(provenance.get("receipt_sha256", "")))
                or not GIT.fullmatch(str(provenance.get("candidate_commit", "")))):
            raise ValueError("Invalid photo issue generation reference")
        receipt_bytes = _local(root, provenance["receipt_path"]).read_bytes()
        if len(receipt_bytes) > 1024 * 1024 or hashlib.sha256(receipt_bytes).hexdigest() != provenance["receipt_sha256"]:
            raise ValueError("Photo issue native receipt hash mismatch")
        receipt = json.loads(receipt_bytes)
        branch = ("native-image-candidate/" + source["slug"] + "/" + source["article_sha256"][:16]
                  + "-" + hashlib.sha256(logical.encode("utf-8")).hexdigest()[:12])
        if (provenance.get("candidate_branch") != branch or receipt.get("version") != 1
                or receipt.get("kind") != "native_image_candidate" or receipt.get("status") != "awaiting_visual_review"
                or receipt.get("repository") != "RollNuts/mihassei-news"
                or receipt.get("slug") != source["slug"] or receipt.get("article_sha256") != source["article_sha256"]
                or receipt.get("logical_run_id") != logical or receipt.get("jpeg", {}).get("sha256") != sha
                or receipt.get("jpeg", {}).get("bytes") != len(data)
                or (receipt.get("jpeg", {}).get("width"), receipt.get("jpeg", {}).get("height")) != (1200, 675)
                or receipt.get("source", {}).get("sha256") != image.get("source_png_sha256")
                or not SHA.fullmatch(str(image.get("source_png_sha256", "")))):
            raise ValueError("Photo issue native generation binding mismatch")
        if is_article:
            snapshot = issue["article_photo_sources"][source["slug"]]
            manifest = snapshot["manifest"]
            if (receipt.get("identity") != manifest["native_candidate"].get("identity")
                    or receipt.get("generation", {}).get("prompt") != manifest.get("generation_prompt")
                    or receipt.get("source", {}).get("bytes") != manifest.get("source_png_bytes")
                    or (manifest.get("width"), manifest.get("height")) != (1200, 675)
                    or _stamp(snapshot["accepted_review"]["reviewed_at"]) < _stamp(receipt.get("generation", {}).get("observed_at"))):
                raise ValueError("Accepted article-photo manifest/native receipt mismatch")
        generation, baseline, raw_source = receipt.get("generation"), receipt.get("baseline"), receipt.get("source")
        if not isinstance(generation, dict) or not isinstance(baseline, dict) or not isinstance(raw_source, dict):
            raise ValueError("Incomplete native photo receipt")
        prompt = _text(generation.get("prompt"), "native generation prompt")
        expected_identity = hashlib.sha256(json.dumps(
            ["RollNuts/mihassei-news", source["slug"], source["article_sha256"], logical, prompt],
            ensure_ascii=False, separators=(",", ":")).encode("utf-8")).hexdigest()
        protected = baseline.get("protected_hashes", {})
        if (receipt.get("identity") != expected_identity
                or generation.get("prompt_sha256") != hashlib.sha256(prompt.encode("utf-8")).hexdigest()
                or generation.get("capture_kind") not in ("native_tool_result", "recovered_native_output")
                or not GIT.fullmatch(str(baseline.get("commit_sha", "")))
                or not GIT.fullmatch(str(baseline.get("tree_sha", "")))
                or any(not SHA.fullmatch(str(protected.get(key, ""))) for key in
                       ("content/articles.json", "assets/generated/manifest.json", "content/visual_reviews.json"))):
            raise ValueError("Invalid native photo identity/baseline")
        parts = raw_source.get("parts")
        source_size = raw_source.get("bytes")
        candidate_dir = "maintenance/native-image-candidates/" + source["slug"]
        if (not isinstance(parts, list) or not 1 <= len(parts) <= 64
                or type(source_size) is not int or not 33 <= source_size <= 32 * 1024 * 1024
                or receipt["jpeg"].get("path") != candidate_dir + "/candidate.jpg"
                or receipt["jpeg"].get("quality") != 84):
            raise ValueError("Invalid native photo source parts")
        for index, part in enumerate(parts):
            if (not isinstance(part, dict) or part.get("path") != candidate_dir + f"/source.png.part{index:03}"
                    or not SHA.fullmatch(str(part.get("sha256", "")))
                    or not GIT.fullmatch(str(part.get("blob_sha", "")))
                    or type(part.get("bytes")) is not int or not 1 <= part["bytes"] <= 512 * 1024):
                raise ValueError("Invalid native photo source part reference")
        if sum(part["bytes"] for part in parts) != source_size:
            raise ValueError("Native photo source part sizes disagree")
        reviewed_at = _stamp(review.get("reviewed_at"))
        if reviewed_at < _stamp(generation.get("observed_at")) or published_at < reviewed_at:
            raise ValueError("Photo issue publication/review order is invalid")
        if (review.get("decision") != "accepted" or review.get("issue_sha256") != issue["issue_sha256"]
                or review.get("image_sha256") != sha or review.get("master_sha256") != master["sha256"]
                or review.get("cut_id") != cut or _stamp(review.get("reviewed_at")) > now):
            raise ValueError("Photo issue cut has no matching accepted visual review")
        _text(review.get("note"), "visual review note")
        if "body_profile" in issue["model_snapshot"]:
            plan = generation_inputs(issue, cut)
            if (review.get("body_profile_sha256") != plan["body_profile_sha256"]
                    or provenance.get("body_profile_sha256") != plan["body_profile_sha256"]
                    or provenance.get("reference_images") != plan["references"]):
                raise ValueError("Photo issue body plan lacks matching generation/reference/visual review")
        framing = review.get("framing")
        if (type(review.get("swimwear_visible")) is not bool
                or framing not in ("face", "upper_body", "three_quarter", "full_body", "profile", "wide")):
            raise ValueError("Photo review needs observed swimwear/framing")
        swimwear_count += int(review["swimwear_visible"])
        framings.add(framing)
    if swimwear_count < MIN_SWIMWEAR_CUTS:
        raise ValueError("A published photo issue needs at least six reviewed visible-swimwear cuts")
    if not (framings & {"face", "upper_body", "three_quarter", "profile"} and framings & {"full_body", "wide"}):
        raise ValueError("A published photo issue needs near and full/wide framing")
    return issue


def published_issues(data, *, root=ROOT, now=None):
    result = [validate_published_issue(issue, root=root, now=now) for issue in data["issues"] if issue["state"] == "published"]
    return sorted(result, key=lambda issue: issue["published_at"], reverse=True)


def photo_routes(issues):
    return ([index_url()] + [issue_url(issue) for issue in issues]) if issues else []


def generate_photo_rss(issues):
    """Serialize already-validated releases, keeping the news feed separate."""
    from email.utils import format_datetime
    from xml.etree import ElementTree as ET
    site = "https://veripsa.com"
    atom, media = "http://www.w3.org/2005/Atom", "http://search.yahoo.com/mrss/"
    ET.register_namespace("atom", atom)
    ET.register_namespace("media", media)
    rss = ET.Element("rss", version="2.0")
    channel = ET.SubElement(rss, "channel")
    ET.SubElement(channel, "title").text = "週刊グラビア | 未発生新聞（創作写真コラム）"
    ET.SubElement(channel, "link").text = site + index_url()
    ET.SubElement(channel, "description").text = "架空の成人モデルの写真と、5年後を暮らす短いコラム。"
    ET.SubElement(channel, "language").text = "ja"
    ET.SubElement(channel, f"{{{atom}}}link", href=site + feed_url(), rel="self", type="application/rss+xml")
    released = sorted((issue for issue in issues if issue.get("state") == "published"),
                      key=lambda issue: _stamp(issue["published_at"]), reverse=True)
    if released:
        ET.SubElement(channel, "lastBuildDate").text = format_datetime(_stamp(released[0]["published_at"]))
    for issue in released:
        entry = ET.SubElement(channel, "item")
        cover = cover_shot(issue)
        image = site + cover_url(issue)
        ET.SubElement(entry, "title").text = issue["title"] + " | 週刊グラビア（創作写真コラム）"
        ET.SubElement(entry, "link").text = site + issue_url(issue)
        ET.SubElement(entry, "guid", isPermaLink="true").text = site + issue_url(issue)
        ET.SubElement(entry, "pubDate").text = format_datetime(_stamp(issue["published_at"]))
        ET.SubElement(entry, "description").text = issue["summary"]
        ET.SubElement(entry, "enclosure", url=image,
                      length=str(issue["images"][cover["id"]]["bytes"]), type="image/jpeg")
        ET.SubElement(entry, f"{{{media}}}thumbnail", url=image, width="1200", height="675")
        ET.SubElement(entry, f"{{{media}}}content", url=image, medium="image", type="image/jpeg")
        ET.SubElement(entry, f"{{{media}}}description", type="plain").text = cover["alt"]
    return ET.tostring(rss, encoding="unicode")


def build_photo_issues(issues, models, layout, write, output, *, root=ROOT):
    """Copy only already-validated published JPEGs, never receipts/source PNGs."""
    if not issues:
        return
    import shutil
    if __package__:
        from .photo_issue_pages import render_photo_index, render_photo_issue
    else:
        from photo_issue_pages import render_photo_index, render_photo_issue
    write(index_url().lstrip("/") + "index.html", render_photo_index(issues, models, layout))
    for issue in issues:
        write(issue_url(issue).lstrip("/") + "index.html",
              render_photo_issue(issue, issue["model_snapshot"], layout))
        for shot in issue["shots"]:
            image = issue["images"][shot["id"]]
            destination = Path(output) / photo_image_url(issue, shot["id"]).split("?", 1)[0].lstrip("/")
            destination.parent.mkdir(parents=True, exist_ok=True)
            if destination.exists():
                if hashlib.sha256(destination.read_bytes()).hexdigest() != image["sha256"]:
                    raise ValueError("Photo output conflicts with its accepted source bytes")
            else:
                shutil.copy2(_local(root, image["path"]), destination)
    write(feed_url().lstrip("/"), generate_photo_rss(issues))


def photo_sitemap_entries(issues):
    if not issues:
        return []
    newest = max(issues, key=lambda item: item["published_at"])
    return [(index_url(), newest["published_at"], cover_url(newest))] + [
        (issue_url(issue), issue["published_at"], cover_url(issue)) for issue in issues]


def status_report(data):
    """Compact metadata only: accepted rows are not a byte/visual verification."""
    rows = []
    for issue in data["issues"]:
        cuts = {shot["id"] for shot in issue["shots"]}
        accepted = {cut for cut, image in issue["images"].items()
                    if cut in cuts and isinstance(image, dict)
                    and isinstance(image.get("review"), dict)
                    and image["review"].get("decision") == "accepted"}
        holds = issue.get("generation_holds", {})
        if not isinstance(holds, dict):
            raise ValueError("Photo issue generation_holds must be a cut-ID mapping")
        held = sorted(cuts & set(holds))
        missing = sorted(cuts - accepted)
        if held:
            status = "blocked_holds"
            action = ("元claim・失敗来歴を保持。担当が原因と入力の変更を確認して、"
                      "依頼済み範囲の適切な新計画を検証する。同条件再試行・判定迂回はしない。"
                      "全10枚の実採用まではdraftを維持する。")
        elif missing:
            status = "draft_incomplete"
            action = "保存済み候補と既存担当の引継ぎを確認。未完成号はdraftを維持する。"
        else:
            status = "recorded_complete_unverified"
            action = "全写真・原来歴・目視レビューの公開gateを検証する。記録数だけで公開しない。"
        rows.append({"slug": issue["slug"], "issue_sha256": issue["issue_sha256"],
                     "state": issue["state"], "status": status,
                     "recorded_accepted_count": len(accepted), "planned_count": len(cuts),
                     "missing_cut_ids": missing, "held_cut_ids": held, "next_action": action})
    return {"schema_version": 1, "verification": "metadata_only", "fully_verified": False, "issues": rows}


def _verify_plan_references(references, root):
    """Verify the exact face/body JPEGs before returning usable generation inputs."""
    for reference in references:
        data = _local(root, reference["path"]).read_bytes()
        if (not 16_000 <= len(data) <= MAX_SCENE_BYTES
                or hashlib.sha256(data).hexdigest() != reference["sha256"]
                or jpeg_dimensions(data) is None):
            raise ValueError("Photo plan reference JPEG hash/format/size mismatch")


def main(argv=None):
    import argparse
    parser = argparse.ArgumentParser(description="Read-only weekly-photo metadata status; no generation or build.")
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--status", action="store_true", help="Read local issue metadata only")
    mode.add_argument("--model-plan", metavar="MODEL_ID", help="Freeze a prepared model for a new issue")
    mode.add_argument("--cut-plan", metavar="ISSUE_SLUG", help="Read inputs from a new-format frozen issue")
    parser.add_argument("--cut", metavar="01..10", help="Required with --cut-plan")
    parser.add_argument("--json", action="store_true", help="Print compact JSON")
    args = parser.parse_args(argv)
    if bool(args.cut_plan) != bool(args.cut):
        parser.error("--cut-plan requires --cut, and --cut is only valid with --cut-plan")
    data = load_photo_issues()
    try:
        if args.model_plan:
            model = next((model for model in data["models"] if model["id"] == args.model_plan), None)
            snapshot = freeze_model_plan(model)
            references = [snapshot["face_reference"], snapshot["body_reference"]]
            _verify_plan_references(references, ROOT)
            report = {"verification": "metadata_only", "reference_bytes_verified": True,
                      "requires_visual_review": True, "model_snapshot": snapshot}
        elif args.cut_plan:
            issue = next((issue for issue in data["issues"] if issue["slug"] == args.cut_plan), None)
            report = generation_inputs(issue, args.cut)
            _verify_plan_references(report["references"], ROOT)
            report["reference_bytes_verified"] = True
        else:
            report = status_report(data)
    except (ValueError, OSError) as exc:
        parser.error(str(exc))
    if args.json:
        print(json.dumps(report, ensure_ascii=False, separators=(",", ":")))
    elif args.status:
        print("Metadata only; not fully verified.")
        for row in report["issues"]:
            print(row["slug"], row["issue_sha256"], row["state"], row["status"],
                  "recorded accepted=" + str(row["recorded_accepted_count"]) + "/" + str(row["planned_count"]),
                  "missing=" + ",".join(row["missing_cut_ids"]), "held=" + ",".join(row["held_cut_ids"]),
                  row["next_action"])
    else:
        print(json.dumps(report, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
